use js_sys::JsString;
use wasm_bindgen::prelude::*;

// ---------------------------------------------------------------------------
// Tauri IPC bridge — generated by wasm-bindgen from /src/tauri.js.
// This block MUST remain exactly as-is; it is the single entry point into
// the Tauri IPC layer.
// ---------------------------------------------------------------------------
#[wasm_bindgen(module = "/src/tauri.js")]
extern "C" {
    #[wasm_bindgen(catch)]
    async fn invokeCommand(name: &str, args: &JsValue) -> Result<JsValue, JsValue>;
}

// ---------------------------------------------------------------------------
// Direct Tauri command wrappers (not proxied through core_invoke).
// These call Tauri commands that live in the shell, not in the core JSON-RPC
// server — keep them using invokeCommand directly.
// ---------------------------------------------------------------------------

/// Call the Tauri `clone_project` command and return its string reply.
pub async fn clone_project() -> Result<String, JsValue> {
    let args = JsValue::NULL;
    let result = invokeCommand("clone_project", &args).await?;
    if let Some(text) = result.as_string() {
        Ok(text)
    } else if let Some(js) = result.dyn_ref::<JsString>() {
        Ok(js.as_string().unwrap_or_else(|| "Risposta non valida".into()))
    } else {
        Ok("Risposta non valida".into())
    }
}

