// ---------------------------------------------------------------------------
// Low-level core_invoke bridge — wraps the JSON-RPC proxy exposed by the
// Tauri shell as the `core_invoke` command.
// ---------------------------------------------------------------------------

/// Pass an RPC call through to the in-process openhuman-core JSON-RPC server
/// via the Tauri `core_invoke` command.  The shell verifies the bearer token
/// and forwards the request to `http://127.0.0.1:<port>/rpc`.
///
/// `params` must already be a `JsValue` representing a JSON object.  The
/// result is the raw `JsValue` returned by the shell.
pub async fn core_invoke(method: &str, params: JsValue) -> Result<JsValue, JsValue> {
    let obj = js_sys::Object::new();
    js_sys::Reflect::set(&obj, &JsValue::from_str("method"), &JsValue::from_str(method))?;
    js_sys::Reflect::set(&obj, &JsValue::from_str("params"), &params)?;
    let result = invokeCommand("core_invoke", &JsValue::from(obj)).await?;
    Ok(result)
}

// ---------------------------------------------------------------------------
// Private helper — serialise params, invoke RPC, deserialise result.
// ---------------------------------------------------------------------------

/// Invoke a JSON-RPC method, accepting `serde_json::Value` params and
/// returning a `serde_json::Value` result.
///
/// Error path: any serialisation / deserialisation failure or IPC error is
/// surfaced as a human-readable `String` so callers do not have to reason
/// about `JsValue` error types.
async fn invoke_rpc(
    method: &str,
    params: serde_json::Value,
) -> Result<serde_json::Value, String> {
    // Serialize the params struct to a JSON string, then parse it back into a
    // JS value so the Tauri bridge can pass it through without a second
    // serialisation round-trip inside the shell.
    let params_str = serde_json::to_string(&params)
        .map_err(|e| format!("[rpc] params serialisation failed for {method}: {e}"))?;

    let params_js = js_sys::JSON::parse(&params_str)
        .map_err(|e| format!("[rpc] js JSON.parse failed for {method}: {e:?}"))?;

    // Dispatch to the Tauri bridge.
    let result_js = core_invoke(method, params_js)
        .await
        .map_err(|e| format!("[rpc] core_invoke error for {method}: {e:?}"))?;

    // Serialise the JS value back to a Rust string so serde_json can parse it.
    let result_str = js_sys::JSON::stringify(&result_js)
        .map_err(|e| format!("[rpc] result stringify failed for {method}: {e:?}"))?
        .as_string()
        .ok_or_else(|| format!("[rpc] result was not a JS string for {method}"))?;

    serde_json::from_str(&result_str)
        .map_err(|e| format!("[rpc] result deserialisation failed for {method}: {e} — raw: {result_str}"))
}

// ---------------------------------------------------------------------------
// Public typed RPC helpers — one function per JSON-RPC method.
//
// All functions return `Result<serde_json::Value, String>` so the Yew layer
// can pattern-match and dispatch AppActions without knowing anything about
// the wire format.
// ---------------------------------------------------------------------------

/// `core.ping` — check that the embedded core is alive.
/// Params: `{}` — Returns: `{"ok": bool}`
pub async fn ping() -> Result<serde_json::Value, String> {
    invoke_rpc("core.ping", serde_json::json!({})).await
}

/// Convenience wrapper used by the App root to probe core liveness.
/// Returns `true` when the core responds with `{"ok": true}`.
pub async fn core_ping() -> Result<bool, String> {
    let val = ping().await?;
    // The core returns {"ok": true} — treat any truthy value at "ok" as success.
    let ok = val
        .get("ok")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    Ok(ok)
}

/// `openhuman.app_state_snapshot` — full application state from the core.
/// Params: `{}` — Returns: JSON object
pub async fn app_state_snapshot() -> Result<serde_json::Value, String> {
    invoke_rpc("openhuman.app_state_snapshot", serde_json::json!({})).await
}

/// `openhuman.threads_list` — retrieve all threads.
/// Params: `{}` — Returns: `{"result": [...]}`
pub async fn threads_list() -> Result<serde_json::Value, String> {
    invoke_rpc("openhuman.threads_list", serde_json::json!({})).await
}

/// `openhuman.threads_create_new` — create a new thread with optional labels.
/// Params: `{"labels": [...]}` (labels is optional) — Returns: JSON object
pub async fn threads_create_new(
    labels: Option<Vec<String>>,
) -> Result<serde_json::Value, String> {
    let params = match labels {
        Some(l) => serde_json::json!({ "labels": l }),
        None => serde_json::json!({}),
    };
    invoke_rpc("openhuman.threads_create_new", params).await
}

/// `openhuman.threads_delete` — soft-delete a thread.
/// Params: `{"thread_id": str, "deleted_at": str}` — Returns: JSON object
pub async fn threads_delete(
    thread_id: &str,
    deleted_at: &str,
) -> Result<serde_json::Value, String> {
    invoke_rpc(
        "openhuman.threads_delete",
        serde_json::json!({
            "thread_id": thread_id,
            "deleted_at": deleted_at,
        }),
    )
    .await
}

/// `openhuman.threads_messages_list` — list messages in a thread.
/// Params: `{"thread_id": str}` — Returns: `{"result": [...]}`
pub async fn threads_messages_list(thread_id: &str) -> Result<serde_json::Value, String> {
    invoke_rpc(
        "openhuman.threads_messages_list",
        serde_json::json!({ "thread_id": thread_id }),
    )
    .await
}

/// `openhuman.threads_message_append` — append a message to a thread.
/// Params: `{"thread_id": str, "message": {"role": str, "content": str}}`
/// Returns: JSON object
pub async fn threads_message_append(
    thread_id: &str,
    role: &str,
    content: &str,
) -> Result<serde_json::Value, String> {
    invoke_rpc(
        "openhuman.threads_message_append",
        serde_json::json!({
            "thread_id": thread_id,
            "message": {
                "role": role,
                "content": content,
            },
        }),
    )
    .await
}

/// `openhuman.agent_chat` — send a free-form chat message to the agent.
/// Params: `{"message": str, "model_override": str?}` — Returns: JSON object
pub async fn agent_chat(
    message: &str,
    model_override: Option<&str>,
) -> Result<serde_json::Value, String> {
    let params = match model_override {
        Some(m) => serde_json::json!({ "message": message, "model_override": m }),
        None => serde_json::json!({ "message": message }),
    };
    invoke_rpc("openhuman.agent_chat", params).await
}

