/// Persist `key=value` in the app data env file and apply it immediately.
/// Calls the `set_env_var` Tauri command directly (not via core_invoke).
pub async fn set_env_var(key: &str, value: &str) -> Result<(), String> {
    let obj = js_sys::Object::new();
    js_sys::Reflect::set(&obj, &JsValue::from_str("key"), &JsValue::from_str(key))
        .map_err(|e| format!("reflect key: {e:?}"))?;
    js_sys::Reflect::set(&obj, &JsValue::from_str("value"), &JsValue::from_str(value))
        .map_err(|e| format!("reflect value: {e:?}"))?;
    invokeCommand("set_env_var", &JsValue::from(obj))
        .await
        .map_err(|e| format!("set_env_var failed: {e:?}"))?;
    Ok(())
}
